import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json}from './bounded-source-hash-20261026.mjs';
const root='F:/VisibleMedicine/staging/20261027-guided-focus-browser',proposal='F:/VisibleMedicine/staging/20261027-guided-focus-proposal/PROPOSAL.json';assert.equal(hash(proposal),'6aca4f15168ce86def58bb742fc2aa9f350a9965fab2a47d57817fc96d7a5714');
const pin=p=>({path:p,sha256:hash(p)}),build=json(root+'/after-1/BUILD.json');
for(const phase of ['before-1','after-1'])assert(json(root+'/'+phase+'/TERMINAL.json').graceful);
for(const f of build.files)assert.equal(hash(root+'/after-1/'+f.path),f.sha256);
