const evidence={};
for(const m of ['CT','MRI']){const before=root+'/before-1/'+m+'_FOCUS.json',after=root+'/after-1/'+m+'_FOCUS.json',b=json(before),a=json(after);assert.equal(b.before.tag,'INPUT');assert.equal(b.after.tag,'H3');assert.deepEqual(b.errors,[]);assert.equal(a.moved.after.tag,'INPUT');assert.equal(a.moved.after.label,'Synthetic notes');assert(a.moved.hasFocus);assert.equal(a.moved.visibility,'visible');assert.deepEqual(a.moved.errors,[]);for(const v of [a.next,a.plain]){assert.equal(v.active,'H3');assert.equal(v.text,v.heading);assert(v.hasFocus);assert.deepEqual(v.errors,[]);}evidence[m]={before:pin(before),after:pin(after)};}
const out=root+'/VERIFIED_PROPOSAL.json';fs.writeFileSync(out,JSON.stringify({at:new Date().toISOString(),proposal:pin(proposal),bundle:pin(root+'/after-1/BUILD.json'),evidence,actualReactViewerAndNativeFocus:true,syntheticAcquisition:true,inertFrameworkRouter:true,delayedLoadRetainsLaterFocus:true,explicitStepAndInitialFocusPreserved:true,integrated:false,fullTypesOrProductionBuildVerified:false,clinicalApproval:false,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(pin(out)));
